#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.Metas;
using MVZ2.Modding;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        #region 元数据列表
        public ArcadeMetaList? GetArcadeMetaList(string nsp)
        {
            var modResource = main.ResourceManager.GetModResource(nsp);
            if (modResource == null)
                return null;
            return modResource.ArcadeMetaList;
        }
        #endregion

        #region 元数据
        public ArcadeMeta? GetArcadeMeta(NamespaceID? arcade)
        {
            if (!NamespaceID.IsValid(arcade))
                return null;
            var modResource = main.ResourceManager.GetModResource(arcade.SpaceName);
            if (modResource?.ArcadeMetaList == null)
                return null;
            foreach (var m in modResource.ArcadeMetaList.metas)
            {
                if (m.ID == arcade.Path)
                    return m;
            }
            return null;
        }
        #endregion
        public NamespaceID[] GetAllArcadeItems()
        {
            return arcadeCache.ToArray();
        }
        private void LoadUnlocks_Arcade(ModResource resource)
        {
            if (resource.ArcadeMetaList == null)
                return;
            foreach (var meta in resource.ArcadeMetaList.metas)
            {
                AddConditionListUnlocks(meta.HiddenUntil);
            }
        }
        private List<NamespaceID> arcadeCache = new List<NamespaceID>();
    }
}
